class SlidingHLL {
  constructor(K, m) {
    this.hlls = Array.from({length: K}, () => new HyperLogLog(m));
    this.idx = 0;
  }
  update(batch) {
    const i = this.idx % this.hlls.length;
    for (const id of batch) this.hlls[i].add(id);
    this.idx++;
  }
  estimate() {
    const merged = HyperLogLog.merge(this.hlls);
    return merged.estimate();
  }
}
```

